content.css:
/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
.scenario-radar-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  box-sizing: border-box;
  padding-bottom: 24px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  display: flex;
  flex-direction: column;
  color: var(--sr-text);
  background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--sr-soft) 100%);
  --sr-panel-bg: #ffffff;
  --sr-panel-border: var(--bf-rule, #E5E7EB);
  --sr-panel-accent: #E8612A;
  --sr-panel-text: #242424;
  --sr-soft: #F8F9FB;
  --sr-rule: #E5E7EB;
  --sr-text: #242424;
  --sr-muted: #6C757D;
  --sr-insight-font: 11px;
  --sr-insight-header-font: 12px;
}
.scenario-radar-root svg {
  shape-rendering: geometricPrecision;
}
/* ── Content area (chart + secondary + insight panel + strip) ── */
.sr-content-area {
  display: flex;
  flex-direction: row;
  flex: 1;
  min-height: 0;
}
.sr-chart-wrap {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  position: relative;
}
.sr-chart-wrap svg {
  width: 100%;
  height: 100%;
}
/* ── Grid ── */
.sr-grid-ring {
  fill: none;
  stroke-width: 0.5;
}
.sr-grid-spoke {
  stroke-width: 0.5;
}
.sr-grid-label {
  font-size: 10px;
  fill: var(--bf-muted, #667079);
  text-anchor: middle;
}
/* ── Axis labels ── */
.sr-axis-label {
  font-size: 11px;
  fill: var(--bf-text, #242424);
  font-weight: 600;
}
/* ── Scenario polygons ── */
.sr-polygon {
  cursor: pointer;
  transition: opacity 0.15s ease;
}
.sr-polygon:hover {
  filter: brightness(1.1);
}
.sr-polygon.dimmed {
  opacity: 0.12;
}
/* ── Data dots ── */
.sr-dot {
  stroke: var(--bf-tile, #FFFFFF);
  stroke-width: 1.5;
  cursor: pointer;
  transition: opacity 0.15s ease;
}
.sr-dot:hover {
  stroke-width: 2.5;
  filter: brightness(1.15);
}
.sr-dot.dimmed {
  opacity: 0.15;
}
/* ── Data labels ── */
.sr-data-label {
  font-size: 9px;
  fill: var(--bf-muted, #667079);
  pointer-events: none;
  text-anchor: middle;
}
/* ── Target ring ── */
.sr-target-ring {
  fill: none;
  stroke-dasharray: 5 3;
}
/* ── Legend ── */
.sr-legend {
  font-size: 11px;
  fill: var(--bf-muted, #667079);
}
.sr-legend-swatch {
  stroke: var(--bf-tile, #FFFFFF);
  stroke-width: 0.5;
}
.sr-legend-item {
  cursor: pointer;
}
.sr-legend-item:hover {
  opacity: 0.7;
}
/* ── Landing page ── */
.sr-landing {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: var(--bf-muted, #667079);
  font-size: 14px;
  text-align: center;
  padding: 24px;
  box-sizing: border-box;
}
/* ── Empty data message (suite standard) ── */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
/* ── Info button + popover (BFusion brand: circular 20px, italic "i") ── */
.sr-info-bar {
  position: relative;
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
  padding: 6px 10px 4px 10px;
  border-bottom: 1px solid var(--sr-rule);
  background: transparent;
  flex-shrink: 0;
  min-height: 24px;
  z-index: 30;
  box-sizing: border-box;
}
.sr-info-btn {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-muted, #667079);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  line-height: 1;
  cursor: pointer;
  user-select: none;
  transition: all 0.15s ease;
  padding: 0;
}
.sr-info-btn:hover,
.sr-info-btn:focus {
  background: #E8612A;
  color: #fff;
  border-color: #E8612A;
  outline: none;
  transform: scale(1.05);
}
.sr-info-btn:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.sr-info-popover {
  position: absolute;
  top: calc(100% + 4px);
  right: 8px;
  z-index: 40;
  display: none;
  width: 320px;
  max-width: calc(100% - 16px);
  background: var(--bf-tile, #FFFFFF);
  border: 1px solid var(--sr-rule);
  border-radius: 6px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.12);
  padding: 10px 12px;
  font-size: var(--sr-insight-font);
  color: var(--sr-text);
  line-height: 1.4;
}
.sr-info-popover-title {
  font-weight: 700;
  font-size: var(--sr-insight-header-font);
  margin-bottom: 4px;
  color: var(--sr-text);
}
.sr-info-popover-body {
  margin: 0 0 6px 0;
  color: var(--sr-text);
}
.sr-info-popover-subtitle {
  font-weight: 600;
  color: var(--sr-muted);
  margin-top: 6px;
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  font-size: 10px;
}
.sr-info-popover-list {
  margin: 0;
  padding-left: 18px;
  color: var(--sr-text);
}
.sr-info-popover-list li {
  margin-bottom: 3px;
}
/* ── Secondary mini chart ── */
.sr-secondary-wrap {
  display: flex;
  flex-direction: column;
  width: 170px;
  min-width: 170px;
  flex: 0 0 170px;
  border-left: 1px solid var(--sr-panel-border);
  padding: 10px 10px 10px 12px;
  box-sizing: border-box;
  background: rgba(250, 251, 252, 0.6);
  overflow-y: auto;
  overflow-x: hidden;
}
.sr-secondary-title {
  font-weight: 700;
  font-size: 12px;
  color: var(--bf-text, #242424);
  padding-bottom: 4px;
  border-bottom: 2px solid var(--sr-panel-accent);
}
.sr-secondary-subtitle {
  font-size: 10px;
  color: var(--bf-muted, #667079);
  margin-top: 2px;
  margin-bottom: 8px;
}
.sr-secondary-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.sr-secondary-item {
  cursor: pointer;
  padding: 3px 2px;
  border-radius: 3px;
  transition: background 0.12s ease;
}
.sr-secondary-item:hover {
  background: rgba(232, 97, 42, 0.07);
}
.sr-secondary-name-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 10px;
  margin-bottom: 2px;
}
.sr-secondary-name {
  color: var(--bf-text, #242424);
  font-weight: 500;
}
.sr-secondary-value {
  color: var(--bf-muted, #667079);
  font-weight: 600;
  font-size: 9.5px;
}
.sr-secondary-track {
  height: 6px;
  background: var(--bf-surface-alt, #F4F5F7);
  border-radius: 3px;
  overflow: hidden;
}
.sr-secondary-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.25s ease;
}
/* ── Insight Panel (flex sidebar) — BFusion brand ── */
.sr-insight-panel {
  display: none;
  width: 250px;
  min-width: 220px;
  max-width: 320px;
  flex: 0 0 250px;
  border-left: 1px solid var(--sr-rule);
  background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--sr-soft) 100%);
  color: var(--sr-panel-text);
  padding: 12px 12px 14px 14px;
  box-sizing: border-box;
  font-size: var(--sr-insight-font);
  line-height: 1.4;
  overflow-y: auto;
  overflow-x: hidden;
}
.sr-insight-title {
  font-weight: 700;
  font-size: var(--sr-insight-header-font);
  color: var(--sr-text);
  margin: 0 0 8px 0;
  padding-bottom: 4px;
  border-bottom: 2px solid var(--sr-panel-accent);
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.sr-insight-count {
  font-weight: 500;
  font-size: 10px;
  color: var(--sr-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.sr-insight-collapse-row {
  display: flex;
  justify-content: flex-end;
  margin: -4px -4px 2px 0;
}
.sr-insight-collapse-btn {
  font-size: 12px;
  color: var(--sr-muted);
  cursor: pointer;
  user-select: none;
  padding: 2px 7px;
  border-radius: 50%;
  line-height: 1;
  transition: background 0.12s ease, color 0.12s ease;
}
.sr-insight-collapse-btn:hover {
  background: var(--sr-panel-accent);
  color: #fff;
}
/* Thin strip shown when the panel is collapsed (click to re-expand) */
.sr-insight-strip {
  display: none;
  flex: 0 0 26px;
  width: 26px;
  min-width: 26px;
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-surface-alt, #F4F5F7);
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
  color: var(--bf-muted, #667079);
  gap: 10px;
  user-select: none;
}
.sr-insight-strip:hover {
  background: var(--bf-rule, #E5E7EB);
  color: var(--bf-text, #242424);
  outline: none;
}
.sr-insight-strip-arrow {
  font-size: 10px;
  user-select: none;
  color: #D97B29;
  line-height: 1;
}
.sr-insight-strip-label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: 9px;
  font-weight: 650;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--bf-muted, #667079);
}
/* KPI tiles */
.sr-kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin: 4px 0 10px 0;
}
.sr-kpi {
  --sr-kpi-accent: var(--sr-panel-accent);
  background: var(--bf-tile, #FFFFFF);
  border: 1px solid var(--sr-rule);
  border-left: 3px solid var(--sr-kpi-accent);
  border-radius: 4px;
  padding: 5px 7px;
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}
.sr-kpi__value {
  font-weight: 700;
  font-size: 13px;
  color: var(--sr-text);
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sr-kpi__label {
  font-size: 9.5px;
  color: var(--sr-muted);
  text-transform: uppercase;
  letter-spacing: 0.4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sr-insight-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 3px 0;
  border-bottom: 1px dashed var(--sr-rule);
}
.sr-insight-row:last-child {
  border-bottom: none;
}
.sr-insight-label {
  color: var(--sr-muted);
  font-size: 10.5px;
}
.sr-insight-value {
  font-weight: 600;
  color: var(--sr-text);
  font-variant-numeric: tabular-nums;
}
.sr-insight-dist-title {
  font-weight: 700;
  color: var(--sr-text);
  margin: 10px 0 4px 0;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
/* ── Smart Insights callouts ── */
.sr-smart-insights {
  margin-top: 12px;
  padding-top: 8px;
  border-top: 1px solid var(--sr-rule);
}
.sr-callout {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 6px 8px;
  margin-top: 6px;
  font-size: var(--sr-insight-font);
  line-height: 1.4;
  border-radius: 4px;
  border-left: 3px solid transparent;
  background: var(--bf-tile, #FFFFFF);
}
.sr-callout-icon {
  flex-shrink: 0;
  font-weight: 700;
  font-size: 11px;
  width: 12px;
  text-align: center;
  line-height: 1.35;
}
.sr-callout-text {
  color: var(--sr-panel-text);
}
.sr-callout--lever {
  background: rgba(232, 97, 42, 0.08);
  border-left-color: var(--sr-panel-accent);
}
.sr-callout--lever .sr-callout-icon {
  color: var(--sr-panel-accent);
}
.sr-callout--warn {
  background: rgba(231, 76, 60, 0.08);
  border-left-color: #e74c3c;
}
.sr-callout--warn .sr-callout-icon {
  color: #c62828;
}
.sr-callout--info {
  background: rgba(127, 140, 141, 0.1);
  border-left-color: var(--bf-muted, #667079);
}
.sr-callout--info .sr-callout-icon {
  color: var(--bf-muted, #667079);
}
/* ── License Badge & Watermark ── */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
